package indexroom

import (
	"errors"
	"fmt"
	"strings"
	"testing"
)

// timeChain builds a chain whose blocks carry the given per-height timestamps
// (nil entry means a missing timestamp).
func timeChain(t *testing.T, times ...*int64) *Index {
	t.Helper()
	index := New()
	for i, when := range times {
		height := int64(i + 1)
		parent := "genesis"
		if height > 1 {
			parent = fmt.Sprintf("h%d", height-1)
		}
		block := Block{
			Height: height,
			Hash:   fmt.Sprintf("h%d", height),
			Parent: parent,
			Txs:    []string{"a"},
			Time:   when,
		}
		if err := index.Append(block); err != nil {
			t.Fatalf("setup append at %d: %v", height, err)
		}
	}
	return index
}

func TestQueryTxsCursorDiesOnInRangeTimestampChange(t *testing.T) {
	t.Run("reorg changes timestamp in range", func(t *testing.T) {
		idx := timeChain(t, intptr(10), intptr(20), intptr(30))
		first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
		if _, err := idx.Reorg([]Block{
			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: intptr(999)},
			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: intptr(30)},
		}); err != nil {
			t.Fatal(err)
		}
		if _, err := idx.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor}); !errors.Is(err, ErrQueryChanged) {
			t.Fatalf("err=%v, want ErrQueryChanged", err)
		}
	})

	t.Run("missing becomes known in range", func(t *testing.T) {
		idx := timeChain(t, intptr(10), nil, intptr(30))
		first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
		if _, err := idx.Reorg([]Block{
			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: intptr(20)},
		}); err != nil {
			t.Fatal(err)
		}
		if _, err := idx.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor}); !errors.Is(err, ErrQueryChanged) {
			t.Fatalf("err=%v, want ErrQueryChanged", err)
		}
	})

	t.Run("restore changes timestamp in range", func(t *testing.T) {
		idx := timeChain(t, intptr(10), intptr(20), intptr(30))
		first, _ := idx.QueryTxs(TxQuery{PageSize: 1})
		snap := `{"version":2,"tip":3,"blocks":[` +
			`{"height":1,"hash":"h1","parent":"genesis","txs":["a"],"timestamp":10},` +
			`{"height":2,"hash":"h2","parent":"h1","txs":["a"],"timestamp":21},` +
			`{"height":3,"hash":"h3","parent":"h2","txs":["a"],"timestamp":30}` +
			`]}`
		if err := idx.Restore(strings.NewReader(snap)); err != nil {
			t.Fatal(err)
		}
		if _, err := idx.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor}); !errors.Is(err, ErrQueryChanged) {
			t.Fatalf("err=%v, want ErrQueryChanged", err)
		}
	})
}

func TestQueryTxsCursorSurvivesTimestampChangeOutsideRange(t *testing.T) {
	index := timeChain(t, intptr(10), intptr(20), intptr(30), intptr(40))
	// Pin the query to heights 1..2.
	first, err := index.QueryTxs(TxQuery{From: 1, To: 2, PageSize: 1})
	if err != nil {
		t.Fatal(err)
	}
	// Change only the timestamp of height 4, outside the pinned range.
	if _, err := index.Reorg([]Block{
		{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: intptr(30)},
		{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"a"}, Time: intptr(400)},
	}); err != nil {
		t.Fatal(err)
	}
	page, err := index.QueryTxs(TxQuery{From: 1, To: 2, PageSize: 1, Cursor: first.NextCursor})
	if err != nil {
		t.Fatalf("out-of-range time change killed the cursor: %v", err)
	}
	if page.TotalMatches != 2 || page.ToHeight != 2 {
		t.Fatalf("unexpected page: %+v", page)
	}
}

func TestQueryTxsCursorSurvivesIdenticalTimestamps(t *testing.T) {
	index := timeChain(t, intptr(10), intptr(20), intptr(30))
	first, err := index.QueryTxs(TxQuery{PageSize: 1})
	if err != nil {
		t.Fatal(err)
	}
	// Reorg that replays the branch with identical hashes, txs, and times.
	if _, err := index.Reorg([]Block{
		{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: intptr(20)},
		{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: intptr(30)},
	}); err != nil {
		t.Fatal(err)
	}
	pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: first.NextCursor})
	var hits int
	for _, page := range pages {
		if page.TotalMatches != 3 || page.ToHeight != 3 {
			t.Fatalf("stats changed after identical-time replay: %+v", page)
		}
		hits += len(page.Hits)
	}
	if hits != 2 { // the first page already consumed height 1
		t.Fatalf("continuation yielded %d hits, want 2", hits)
	}
}

package indexroom

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"sort"
)

// txFilter is the single canonical form of a query's TxIDs argument, shared by
// the paginated scan, time-window statistics, and continuation-cursor
// validation so that exact matching, duplicate handling, and set equivalence
// live in one place.
//
// Identifiers match by exact string comparison: case, leading and trailing
// whitespace, and string boundaries all matter, so the sets {"ab","c"} and
// {"a","bc"} differ. Ordering and repetitions in the caller's list do not:
// ["a","b","a"] and ["b","a"] canonicalize to one set. A filter built from no
// identifiers (a nil or empty list) is unrestricted and matches every
// occurrence, including empty identifiers; that is distinct from the
// one-element set {""}, which matches only empty-identifier occurrences.
//
// A txFilter is read-only after construction. Construction only reads the
// caller's slice, never reorders, deduplicates, or otherwise mutates it.
type txFilter struct {
	// members holds each distinct identifier once. A nil map means the
	// filter is unrestricted; a populated list never canonicalizes to an
	// empty map, so {""} (one entry) cannot collapse into the nil case.
	members map[string]struct{}
	// digest summarizes the deduplicated, sorted set and is byte-identical
	// to the value historically stored in the v1 cursor's set field, so
	// existing cursors keep validating. It is set even for the unrestricted
	// filter, whose digest is the hash of the empty entry sequence.
	digest []byte
}

// newTxFilter canonicalizes an identifier list. The passed slice is never
// modified.
func newTxFilter(txIDs []string) txFilter {
	if len(txIDs) == 0 {
		// No entries at all: hash of the empty sequence, matching the value
		// cursors carried for an absent filter.
		return txFilter{digest: hashTxIDs(nil)}
	}
	members := make(map[string]struct{}, len(txIDs))
	unique := make([]string, 0, len(txIDs))
	for _, id := range txIDs {
		if _, ok := members[id]; ok {
			continue
		}
		members[id] = struct{}{}
		unique = append(unique, id)
	}
	sort.Strings(unique)
	return txFilter{members: members, digest: hashTxIDs(unique)}
}

// matches reports whether one on-chain occurrence belongs in the answer.
func (f txFilter) matches(id string) bool {
	if f.members == nil {
		return true
	}
	_, ok := f.members[id]
	return ok
}

// hexDigest is the cursor encoding of the set summary; two filters produce the
// same value exactly when their identifier sets are equal, so it is both the
// value minted into a first-page cursor and the continuation equivalence key.
func (f txFilter) hexDigest() string {
	return hex.EncodeToString(f.digest)
}

// hashTxIDs hashes the already deduplicated, sorted identifiers with an
// 8-byte length prefix each, so differently concatenated spellings cannot
// collide: {"ab","c"} serializes differently from {"a","bc"}.
func hashTxIDs(sorted []string) []byte {
	h := sha256.New()
	var lenBuf [8]byte
	for _, id := range sorted {
		binary.BigEndian.PutUint64(lenBuf[:], uint64(len(id)))
		h.Write(lenBuf[:])
		h.Write([]byte(id))
	}
	return h.Sum(nil)
}

