188	// bucketBoundary returns Start + step*index, saturated at MaxInt64 instead
189	// of overflowing. Callers cut saturated and trailing boundaries back to the
190	// requested window end.
191	func bucketBoundary(start, step, index int64) int64 {
192		offset := saturatingMul(step, index)
193		if offset > 1<<63-1-start {
194			return 1<<63 - 1
195		}
196		return start + offset
197	}
