199	// saturatingMul multiplies non-negative a and b, saturating at MaxInt64.
200	func saturatingMul(a, b int64) int64 {
201		if a == 0 || b == 0 {
202			return 0
203		}
204		if a > (1<<63-1)/b {
205			return 1<<63 - 1
206		}
207		return a * b
